import React, { FormEvent, useState } from 'react';

const FORMSPARK_FORM_ID = process.env.NEXT_PUBLIC_FORMSPARK_FORM_ID!;

interface ContactFormData {
  name: string;
  email: string;
  message: string;
}

export function ContactForm(): JSX.Element {
  const [formData, setFormData] = useState<ContactFormData>({
    name: '',
    email: '',
    message: '',
  });
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');

  const handleSubmit = async (e: FormEvent<HTMLFormElement>): Promise<void> => {
    e.preventDefault();
    setStatus('submitting');

    try {
      const response = await fetch(
        `https://submit.formspark.io/f/${FORMSPARK_FORM_ID}`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Accept: 'application/json',
          },
          body: JSON.stringify(formData),
        }
      );

      if (!response.ok) {
        throw new Error(`Submission failed with status: ${response.status}`);
      }

      setStatus('success');
      setFormData({ name: '', email: '', message: '' });
    } catch (err) {
      console.error('Form submission error:', err);
      setStatus('error');
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="text"
        placeholder="Your name"
        value={formData.name}
        onChange={(e) => setFormData((prev) => ({ ...prev, name: e.target.value }))}
        required
      />
      <input
        type="email"
        placeholder="Your email"
        value={formData.email}
        onChange={(e) => setFormData((prev) => ({ ...prev, email: e.target.value }))}
        required
      />
      <textarea
        placeholder="Your message"
        value={formData.message}
        onChange={(e) => setFormData((prev) => ({ ...prev, message: e.target.value }))}
        required
      />
      <button type="submit" disabled={status === 'submitting'}>
        {status === 'submitting' ? 'Sending...' : 'Send Message'}
      </button>
      {status === 'success' && <p>Message sent successfully!</p>}
      {status === 'error' && <p>Something went wrong. Please try again.</p>}
    </form>
  );
}

import React, { FormEvent } from 'react';
import { useFormspark } from '@formspark/use-formspark';

const FORMSPARK_FORM_ID = process.env.NEXT_PUBLIC_FORMSPARK_FORM_ID!;

interface NewsletterFormData {
  email: string;
  firstName?: string;
}

export function NewsletterSignup(): JSX.Element {
  const [submit, submitting] = useFormspark({
    formId: FORMSPARK_FORM_ID,
  });

  const [email, setEmail] = React.useState('');
  const [firstName, setFirstName] = React.useState('');
  const [done, setDone] = React.useState(false);

  const handleSubmit = async (e: FormEvent<HTMLFormElement>): Promise<void> => {
    e.preventDefault();

    const data: NewsletterFormData = { email };
    if (firstName) data.firstName = firstName;

    await submit(data);
    setDone(true);
    setEmail('');
    setFirstName('');
  };

  if (done) {
    return <p>Thanks for subscribing!</p>;
  }

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="text"
        placeholder="First name (optional)"
        value={firstName}
        onChange={(e) => setFirstName(e.target.value)}
      />
      <input
        type="email"
        placeholder="Email address"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        required
      />
      {/* Honeypot field to catch bots — must remain hidden */}
      <input type="text" name="_honeypot" style={{ display: 'none' }} />
      <button type="submit" disabled={submitting}>
        {submitting ? 'Subscribing...' : 'Subscribe'}
      </button>
    </form>
  );
}
